def terms(s):
 return[(int(m[1]or 1),m[2])for t in s.split('+')for m in [re.fullmatch(r'(\d+)?(.+)',t)]]
for i,row in enumerate(RX[:20]):
 name,eq,*_=row;left,right=map(terms,eq.split('→'));a,af=left[0];basis=a*mass(af);given=basis*.75;pf=right[0][1];pMass=right[0][0]*mass(pf)*.75;other=(left[1]if len(left)>1 else right[1]);of=other[1];om=other[0]*mass(of)*.75
 inp=dict(equation=eq,givenFormula=af,givenMass=given,productFormula=pf,productMass=pMass,otherFormula=of,otherMass=om,otherSide='reactant'if len(left)>1 else'product',yieldPercent=80,variant='ONE_MASS_EXTENT_PER_REACTION');aw=', '.join(f'{e}={AW[e]}'for e in sorted(set(e for n,f in left+right for e in atoms(f))))
